     1	/**
     2	 * Keyboard-shortcut matching, split out of `useKeyboardShortcut` so the
     3	 * modifier rules can be unit tested without a DOM event loop.
     4	 *
     5	 * A shortcut is written as a list of tokens, e.g. `["mod", "k"]` or
     6	 * `["shift", "?"]`. `mod` means Meta on Apple platforms and Control elsewhere,
     7	 * which is what every desktop app does and what users expect from Ctrl+K.
     8	 */
     9	
    10	export type ShortcutModifier = "mod" | "ctrl" | "meta" | "alt" | "shift";
    11	
    12	const MODIFIERS: readonly string[] = ["mod", "ctrl", "meta", "alt", "shift"];
    13	
    14	export interface ShortcutEventLike {
    15	  readonly key: string;
    16	  readonly ctrlKey: boolean;
    17	  readonly metaKey: boolean;
    18	  readonly altKey: boolean;
    19	  readonly shiftKey: boolean;
    20	}
    21	
    22	export interface ParsedShortcut {
    23	  readonly modifiers: readonly ShortcutModifier[];
    24	  readonly key: string | null;
    25	}
    26	
    27	export function parseShortcut(keys: readonly string[]): ParsedShortcut {
    28	  const modifiers: ShortcutModifier[] = [];
    29	  let key: string | null = null;
    30	
    31	  for (const raw of keys) {
    32	    const token = raw.trim().toLowerCase();
    33	    if (token.length === 0) continue;
    34	    if (MODIFIERS.includes(token)) {
    35	      modifiers.push(token as ShortcutModifier);
    36	    } else {
    37	      key = token;
    38	    }
    39	  }
    40	
    41	  return { modifiers, key };
    42	}
    43	
    44	/** True when `mod` should resolve to Meta rather than Control. */
    45	export function prefersMetaKey(platform: string): boolean {
    46	  return /mac|iphone|ipad|ipod/i.test(platform);
    47	}
    48	
    49	export function matchesShortcut(
    50	  keys: readonly string[],
    51	  event: ShortcutEventLike,
    52	  platform = "",
    53	): boolean {
    54	  const { modifiers, key } = parseShortcut(keys);
    55	  if (key === null) return false;
    56	  if (event.key.toLowerCase() !== key) return false;
    57	
    58	  const useMeta = prefersMetaKey(platform);
    59	  const wantCtrl =
    60	    modifiers.includes("ctrl") || (modifiers.includes("mod") && !useMeta);
    61	  const wantMeta =
    62	    modifiers.includes("meta") || (modifiers.includes("mod") && useMeta);
    63	  const wantAlt = modifiers.includes("alt");
    64	  const wantShift = modifiers.includes("shift");
    65	
    66	  return (
    67	    event.ctrlKey === wantCtrl &&
    68	    event.metaKey === wantMeta &&
    69	    event.altKey === wantAlt &&
    70	    event.shiftKey === wantShift
    71	  );
    72	}
    73	
    74	/** Renders a shortcut for display next to a command palette entry. */
    75	export function formatShortcut(
    76	  keys: readonly string[],
    77	  platform = "",
    78	): string {
    79	  const useMeta = prefersMetaKey(platform);
    80	  return keys
    81	    .map((raw) => {
    82	      const token = raw.trim().toLowerCase();
    83	      if (token === "mod") return useMeta ? "⌘" : "Ctrl";
    84	      if (token === "meta") return "⌘";
    85	      if (token === "ctrl") return "Ctrl";
    86	      if (token === "alt") return useMeta ? "⌥" : "Alt";
    87	      if (token === "shift") return "⇧";
    88	      return token.length === 1 ? token.toUpperCase() : token;
    89	    })
    90	    .join(useMeta ? "" : "+");
    91	}
