     1	"use client";
     2	
     3	/**
     4	 * Global keydown binding with modifier matching.
     5	 */
     6	import { useEffect, useRef } from "react";
     7	import { matchesShortcut } from "./shortcut-match";
     8	
     9	/** Typing in one of these should never trigger a global shortcut. */
    10	const EDITABLE_TAGS: readonly string[] = ["INPUT", "TEXTAREA", "SELECT"];
    11	
    12	function isTypingTarget(target: EventTarget | null): boolean {
    13	  if (target === null || !(target instanceof HTMLElement)) return false;
    14	  return EDITABLE_TAGS.includes(target.tagName) || target.isContentEditable;
    15	}
    16	
    17	export function useKeyboardShortcut(
    18	  keys: readonly string[],
    19	  handler: () => void,
    20	  enabled = true,
    21	): void {
    22	  const handlerRef = useRef(handler);
    23	  useEffect(() => {
    24	    handlerRef.current = handler;
    25	  }, [handler]);
    26	
    27	  const signature = keys.join("+");
    28	
    29	  useEffect(() => {
    30	    if (!enabled || signature.length === 0) return;
    31	    const tokens = signature.split("+");
    32	
    33	    function onKeyDown(event: KeyboardEvent): void {
    34	      const platform =
    35	        typeof navigator === "undefined" ? "" : navigator.platform;
    36	      if (!matchesShortcut(tokens, event, platform)) return;
    37	      // A bare letter shortcut must not fire while the user is writing.
    38	      if (
    39	        isTypingTarget(event.target) &&
    40	        !event.metaKey &&
    41	        !event.ctrlKey
    42	      ) {
    43	        return;
    44	      }
    45	      event.preventDefault();
    46	      handlerRef.current();
    47	    }
    48	
    49	    window.addEventListener("keydown", onKeyDown);
    50	    return () => window.removeEventListener("keydown", onKeyDown);
    51	  }, [signature, enabled]);
    52	}
